<?php use CMS\Core\Csrf; ?>
<header class="page-header editor-header"><div><a class="back-link" href="<?= e(admin_url('/content-models')) ?>">← Content models</a><p class="eyebrow">Reusable component</p><h1><?= $componentId?e($component['name']):'New component' ?></h1><p class="muted">Group fields that belong together, then embed the component once or as a repeating list in any content model.</p></div></header>
<?php if (!empty($created)): ?><div class="notice success">Component created. Add its fields below.</div><?php endif; ?><?php if (!empty($saved)): ?><div class="notice success">Component saved.</div><?php endif; ?><?php if (!empty($fieldCreated)||!empty($fieldSaved)): ?><div class="notice success">Component field saved.</div><?php endif; ?><?php if (!empty($fieldDeleted)): ?><div class="notice success">Unused component field deleted.</div><?php endif; ?><?php if (!empty($fieldArchived)): ?><div class="notice success">Component field archived. Existing structured values are preserved.</div><?php endif; ?><?php if (!empty($fieldRestored)): ?><div class="notice success">Component field restored.</div><?php endif; ?>
<?php if ($errors): ?><div class="alert error"><ul><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form method="post" action="<?= e($componentId?admin_url('/components/'.$componentId.'/edit'):admin_url('/components/new')) ?>" class="card editor-card stack" data-component-form><?= Csrf::field() ?><label>Name<input name="name" value="<?= e($component['name']) ?>" maxlength="120" required placeholder="Health test" data-component-name></label><label>Description<textarea name="description" rows="3" maxlength="500"><?= e($component['description']) ?></textarea></label><details class="advanced-panel"><summary>Advanced identity</summary><div class="advanced-panel-body"><label>Internal key<input name="slug" value="<?= e($component['slug']) ?>" maxlength="100" placeholder="health-test" <?= $componentId?'readonly':'' ?> data-component-key><small class="field-help"><?= $componentId?'Stable after creation so models using this component remain compatible.':'Generated automatically from the component name.' ?></small></label></div></details><label>Status<select name="status"><option value="active" <?= $component['status']==='active'?'selected':'' ?>>Active</option><option value="disabled" <?= $component['status']==='disabled'?'selected':'' ?>>Disabled</option></select></label><div class="form-actions"><button class="button" type="submit"><?= $componentId?'Save component':'Create component' ?></button></div></form>
<?php if ($componentId): ?><section class="card content-card"><div class="section-heading"><div><p class="eyebrow">Structure</p><h2>Component fields</h2></div><a class="button" href="<?= e(admin_url('/components/'.$componentId.'/fields/new')) ?>">Add field</a></div><?php if (!$fields): ?><div class="empty-state compact"><p>Add fields such as Test, Result, Date and Document.</p></div><?php else: ?><div class="schema-field-list" data-schema-sortable data-reorder-url="<?= e(admin_url('/components/'.$componentId.'/fields/reorder')) ?>" data-reorder-token="<?= e(Csrf::token()) ?>"><?php foreach ($fields as $field): ?><div class="schema-field-row" draggable="true" data-field-id="<?= (int)$field['id'] ?>"><button type="button" class="schema-drag" data-drag-handle aria-label="Drag <?= e($field['label']) ?> to reorder">::</button><a class="schema-field-main" href="<?= e(admin_url('/components/'.$componentId.'/fields/'.(int)$field['id'].'/edit')) ?>"><strong><?= e($field['label']) ?></strong><small><?= e($field['field_key']) ?> - <?= e(CMS\Core\ContentModels::fieldTypes()[$field['field_type']]??$field['field_type']) ?></small></a><div class="schema-field-actions"><button type="button" class="text-link" data-move-field="up" aria-label="Move <?= e($field['label']) ?> up">Up</button><button type="button" class="text-link" data-move-field="down" aria-label="Move <?= e($field['label']) ?> down">Down</button><span>#<?= (int)$field['sort_order'] ?></span></div></div><?php endforeach; ?></div><?php endif; ?></section><?php if (!empty($archivedFields)): ?><section class="card content-card"><div class="section-heading"><div><p class="eyebrow">Safety archive</p><h2>Archived component fields</h2><p class="muted">Existing nested values are preserved.</p></div></div><div class="schema-field-list"><?php foreach ($archivedFields as $field): ?><div class="schema-field-row"><span class="schema-drag" aria-hidden="true">--</span><div class="schema-field-main"><strong><?= e($field['label']) ?></strong><small><?= e($field['field_key']) ?> - archived</small></div><form method="post" action="<?= e(admin_url('/components/'.$componentId.'/fields/'.(int)$field['id'].'/restore')) ?>"><?= Csrf::field() ?><button class="button secondary small">Restore field</button></form></div><?php endforeach; ?></div></section><?php endif; ?><script src="/assets/js/schema-sortable.js?v=<?= e(app_version()) ?>" defer></script><script src="/assets/js/schema-fields.js?v=<?= e(app_version()) ?>" defer></script>
<section class="danger-zone"><div><strong>Delete component</strong><p><?= $inUse?'This component is currently used by a content model and cannot be deleted.':'Deleting an unused component is permanent.' ?></p></div><?php if (!$inUse): ?><form method="post" action="<?= e(admin_url('/components/'.$componentId.'/delete')) ?>"><?= Csrf::field() ?><label class="confirm-check"><input type="checkbox" name="confirm_delete" value="1" required> I understand.</label><button class="button danger">Delete component</button></form><?php endif; ?></section><?php endif; ?>
